s":[],"menuSection":"bar","positioning":"Для знакомства с домашней линейкой и сравнения вкусов.","subcategory":"Домашние","tastingNotes":"Ежевика, хвойно-можжевеловые оттенки и ягодная кислинка.","countryCategory":"Беларусь, Минск — позиция домашней линейки бара; настойка.","productionMethod":"Настаивание вкусового сырья на алкогольной основе с последующим отделением твёрдых компонентов.","styleDescription":"Фруктовая или ягодно-пряная домашняя настойка."}},{"id":"rvb-wine-13","patch":{"fact":"","garnish":"Подавать при 16–18 °C.","gastronomy":"Мясо на гриле, дичь, запечённые овощи, блюда с пряностями и полутвёрдые сыры."},"before":{"id":"rvb-wine-13","fact":"Производитель рекомендует подавать при 16–18 °C; среди сочетаний — запечённые овощи, дичь и сыры.","name":"Casillero del Diablo Carmenere Reserva","brand":"rvb","image":"assets/rvb-menu/wine/13.png","price":"22 р.","taste":"Ягоды · Слива · Пряности","method":"","volume":"150 мл","garnish":"","category":"wine","features":"","imageKind":"photo","gastronomy":"Мясо на гриле, запечённые овощи, блюда с пряностями и полутвёрдые сыры.","description":"Вино: Красное\nСтрана, регион: Чили, Центральная долина (Central Valley)\nСахар: Сухое\nВиноград: Карменер (Carménère)","ingredients":[],"menuSection":"bar","positioning":"Для любителей красных вин с фруктовыми и пряными оттенками.","subcategory":"Красное","wineService":"Бокал","tastingNotes":"Глубокий рубиновый цвет; слива, ежевика, сладкие специи и оттенки перца. Мягкая фактура, умеренные танины, пряный финал.","countryCategory":"Чили, Центральная долина (Central Valley); Красное.","productionMethod":"Брожение сока вместе с кожицей для извлечения цвета и танинов, затем отделение вина и созревание.","styleDescription":"Пряное, ягодное, округлое, со средним или полным телом."}},{"id":"rvb-wine-22","patch":{"fact":""},"before":{"id":"rvb-wine-22","fact":"В купаже Brut Impérial соединяются Пино Нуар, Менье и Шардоне.","name":"Moët & Chandon Brut Impérial","brand":"rvb","image":"assets/rvb-menu/wine/22.png","price":"600 р.","taste":"Яблоко · Цитрус · Бриошь","method":"","volume":"750 мл","garnish":"","category":"wine","features":"","imageKind":"photo","gastronomy":"Аперитив, устрицы, рыба, морепродукты и птица в нежном соусе.","description":"Вино: Белое игристое — шампанское\nСтрана, регион: Франция, Шампань (Champagne AOC)\nСахар: Брют\nВиноград: Пино Нуар (Pinot Noir), Менье (Meunier), Шардоне (Chardonnay)","ingredients":[],"menuSection":"bar","positioning":"Для аперитива и любителей игристого вина.","subcategory":"Шампанское","wineService":"Бутылка","tastingNotes":"Золотисто-соломенный цвет; зелёное яблоко, цитрус, белые цветы и бриошь. Во вкусе — сочные белые фрукты, свежесть и нежная сливочность.","countryCategory":"Франция, Шампань (Champagne AOC); Белое игристое — шампанское.","productionMethod":"Традиционный метод: вторичное брожение в бутылке, выдержка на дрожжевом осадке, удаление осадка и окончательная укупорка.","styleDescription":"Сбалансированное, свежее, элегантное, с тонкими пузырьками и мягкой текстурой."}},{"id":"rvb-wine-24","patch":{"fact":""},"before":{"id":"rvb-wine-24","fact":"Производитель рекомендует сочетания с пряными и кисло-сладкими блюдами, курицей и овощами.","name":"Cono Sur Bicicleta Gewürztraminer","brand":"rvb","image":"assets/rvb-menu/wine/24.webp","price":"150 р.","taste":"Роза · Личи · Пряности","method":"","volume":"750 мл","garnish":"","category":"wine","features":"","imageKind":"photo","gastronomy":"Пряные и кисло-сладкие блюда, китайская и индийская кухня, курица и овощи.","description":"Вино: Белое\nСтрана, регион: Чили.\nВиноград: Гевюрцтраминер (Gewürztraminer)","ingredients":[],"menuSection":"bar","positioning":"Для любителей белых вин с фруктовыми и цветочными оттенками.","subcategory":"Белое","wineService":"Бутылка","tastingNotes":"Зеленовато-соломенный цвет; лепестки розы, личи, свежие фрукты и пряности. Во вкусе косточковые фрукты, округлая фактура и длительное послевкусие.","countryCategory":"Чили; Белое.","productionMethod":"Созревание в ёмкостях из нержавеющей стали.","styleDescription":"Выразительное, ароматное, насыщенное, свежее."}}]$menufacts$::jsonb) as x(id text,patch jsonb,before jsonb);
do $$ begin if (select count(*) from menu_fact_review) <> 108 or exists(select 1 from menu_fact_review r left join public.academy_content c on c.id=r.id where c.id is null or c.kind<>'menu' or not c.published or c.payload<>r.before) then raise exception 'Menu changed since backup';end if;end $$;
update public.academy_content c set payload=c.payload||r.patch,updated_at=now() from menu_fact_review r where c.id=r.id;
select count(*) as reviewed_cards from menu_fact_review;
commit;
